// GENERATED by `go run ./cmd/sdkcontract` in the api repo from internal/sdkcontract. Do not edit; regenerate and copy.
/* eslint-disable */
// Behaviour fixture loader (README.md next to the fixtures is the runner
// contract). Node only: reads api/sdk/behaviour/ copied into the repo.
import { readFileSync } from 'fs';
import { join } from 'path';

export type JsonValue = null | boolean | number | string | JsonValue[] | { [k: string]: JsonValue };
export type BehaviourPlatform = 'android' | 'ios' | 'flutter' | 'react-native';

export const behaviourContractVersion = '1.4.0';
export const behaviourSteps = ["init", "track", "screen", "identify", "reset", "setConsent", "advanceTime", "setNetwork", "background", "foreground", "flush", "recordError", "crashNextLaunch", "restart", "serverResponds", "repeat", "expectRequests", "expectEvents", "expectState"] as const;
export type BehaviourAction = (typeof behaviourSteps)[number];
export const behaviourStateKeys = ["anonymousId", "consent", "queueLength", "replaySampled", "screen", "sessionId", "uploadsPaused", "userId"] as const;

export interface BehaviourStep { action: BehaviourAction; args: JsonValue }
export interface BehaviourNetwork { type: 'wifi' | 'ethernet' | 'cellular' | 'none' | 'other'; generation?: '2g' | '3g' | '4g' | '5g' | 'unknown'; online: boolean }
export interface BehaviourDevice { network: BehaviourNetwork; randomRolls: number[] }
export interface BehaviourCase {
  id: string;
  description: string;
  area: string;
  platforms?: BehaviourPlatform[];
  contract?: string[];
  /** Harness config merged with the case's overrides, by canonical option key. */
  config: Record<string, JsonValue>;
  clock: string;
  device: BehaviourDevice;
  steps: BehaviourStep[];
}
export interface BehaviourHarness {
  apiKey: string; apiUrl: string; config: Record<string, JsonValue>; device: BehaviourDevice;
  clock: string; defaultResponse: { status: number; headers?: Record<string, string> }; ignoredPaths: string[];
}

/** Every case in dir (api/sdk/behaviour), with harness defaults applied. */
export function loadBehaviourCases(dir: string, platform?: BehaviourPlatform): { harness: BehaviourHarness; cases: BehaviourCase[] } {
  const index = JSON.parse(readFileSync(join(dir, 'index.json'), 'utf8'));
  if (index.contractVersion !== behaviourContractVersion) {
    throw new Error('fixtures are contract ' + index.contractVersion + ', loader ' + behaviourContractVersion);
  }
  const harness = index.harness as BehaviourHarness;
  const cases: BehaviourCase[] = [];
  for (const f of index.files as string[]) {
    const file = JSON.parse(readFileSync(join(dir, f), 'utf8'));
    for (const c of file.cases) {
      if (platform && c.platforms && !c.platforms.includes(platform)) continue;
      cases.push({
        id: c.id, description: c.description, area: file.area, platforms: c.platforms, contract: c.contract,
        config: { ...harness.config, ...(c.config ?? {}) },
        clock: c.clock ?? harness.clock,
        device: {
          network: c.device?.network ?? harness.device.network,
          randomRolls: c.device?.randomRolls ?? harness.device.randomRolls,
        },
        steps: (c.steps as Record<string, JsonValue>[]).map(stepOf),
      });
    }
  }
  return { harness, cases };
}

export function stepOf(raw: Record<string, JsonValue>): BehaviourStep {
  const keys = Object.keys(raw);
  if (keys.length !== 1 || !(behaviourSteps as readonly string[]).includes(keys[0]!)) {
    throw new Error('bad step ' + JSON.stringify(raw));
  }
  return { action: keys[0] as BehaviourAction, args: raw[keys[0]!]! };
}

/** Replaces "${i}" in every string (repeat steps, $each matchers). */
export function substitute(v: JsonValue, i: number): JsonValue {
  if (typeof v === 'string') return v.split('${i}').join(String(i));
  if (Array.isArray(v)) return v.map((e) => substitute(e, i));
  if (v && typeof v === 'object') {
    const out: { [k: string]: JsonValue } = {};
    for (const [k, e] of Object.entries(v)) out[substitute(k, i) as string] = substitute(e, i);
    return out;
  }
  return v;
}

/** The value an app passes for fixture input: $number, $repeat, $keys, $list decoded. */
export function decodeInput(v: JsonValue): unknown {
  if (Array.isArray(v)) return v.map(decodeInput);
  if (v && typeof v === 'object') {
    const keys = Object.keys(v);
    if (keys.length === 1) {
      const g = (v as any)[keys[0]!];
      switch (keys[0]) {
        case '$number': return g === 'NaN' ? NaN : g === 'Infinity' ? Infinity : -Infinity;
        case '$repeat': return (g.string as string).repeat(g.count);
        case '$keys': {
          const o: Record<string, unknown> = {};
          for (let i = 0; i < g.count; i++) o[g.prefix + i] = decodeInput(g.value);
          return o;
        }
        case '$list': return Array.from({ length: g.count }, () => decodeInput(g.value));
      }
    }
    const o: Record<string, unknown> = {};
    for (const [k, e] of Object.entries(v)) o[k] = decodeInput(e);
    return o;
  }
  return v;
}
